function output = heartlib(theta, p, q, n, a_tilde, t_tilde)
% output = heartlib(θ, p, q, n, ã, t̃)
%
%    cos from trigonometry
%            b = ∑_i cos(θ)²((p_i - q_i)⋅n_i +((p_i+q_i)×n_i)⋅ã+n_i⋅t̃)²
%            where
%            θ: ℝ: angle of rotation
%            p_i: ℝ^3
%            q_i: ℝ^3
%            n_i: ℝ^3
%            ã: ℝ^3
%            t̃: ℝ^3
    a_tilde = reshape(a_tilde,[],1);
    t_tilde = reshape(t_tilde,[],1);

    dim_0 = size(p, 1);
    assert(numel(theta) == 1);
    assert( isequal(size(p), [dim_0, 3]) );
    assert( isequal(size(q), [dim_0, 3]) );
    assert( isequal(size(n), [dim_0, 3]) );
    assert( numel(a_tilde) == 3 );
    assert( numel(t_tilde) == 3 );

    % b = ∑_i cos(θ)²((p_i - q_i)⋅n_i +((p_i+q_i)×n_i)⋅ã+n_i⋅t̃)²

    sum_0 = 0;
    for i = 1:size(n, 1)
        sum_0 = sum_0 + cos(theta).^2 * (dot((p(i,:)' - q(i,:)'),n(i,:)') + dot((cross((p(i,:)' + q(i,:)'), n(i,:)')),a_tilde) + dot(n(i,:)',t_tilde)).^2;
    end
    b = sum_0;
    output.b = b;
end

